def load() -> pd.DataFrame:
    import glob

    data = []
    files = sorted(glob.glob('data/astronomy/input/geomag_forecast/*.txt'))

    for filepath in files:
        with open(filepath, 'r') as f:
            content = f.read()
            lines = content.split('\n')

            for line in lines:
                if line.startswith('Observed Ap'):
                    parts = line.split()
                    date_str = f"{parts[2]} {parts[3]}"
                    ap_value = int(parts[4])
                    filename = filepath.split('/')[-1]
                    data.append({
                        'filename': filename,
                        'date': date_str,
                        'observed_ap': ap_value
                    })

    return pd.DataFrame(data)

def process(parse_predicted_ap_0309, extract_all_observed_ap) -> pd.DataFrame:
    forecast = parse_predicted_ap_0309.copy()
    forecast.columns = ['date', 'forecast_ap']

    observed = extract_all_observed_ap.copy()

    result_data = []
    for idx, row in forecast.iterrows():
        date = row['date']
        forecast_val = row['forecast_ap']

        obs_row = observed[observed['date'] == date]
        if len(obs_row) > 0:
            actual_val = obs_row.iloc[0]['observed_ap']
        else:
            actual_val = None

        result_data.append({
            'date': date,
            'forecast_ap': forecast_val,
            'actual_ap': actual_val
        })

    return pd.DataFrame(result_data)

def process(compile_forecast_and_actual):
    df = compile_forecast_and_actual.copy()
    df['absolute_error'] = abs(df['forecast_ap'] - df['actual_ap'])
    mae = df['absolute_error'].mean()
    return pd.DataFrame({'MAE': [mae]})
